// services/generate-affiliate-invoice-pdf.js
// Renders a single PAID Commission to a real downloadable PDF invoice --
// same Playwright page.pdf() pattern as services/generate-receipt-pdf.js,
// just a letter-sized document instead of a receipt-width one. Stripe
// Connect transfers (how affiliates actually get paid) don't come with a
// hosted PDF the way Stripe customer invoices do, so this is generated by
// ReceipTap itself rather than linked out to Stripe.

const ejs = require('ejs');
const path = require('path');
const fs = require('fs');
const { chromium } = require('playwright');

const VIEWS_DIR = path.join(__dirname, '..', 'views');

// Embedded as a data URI rather than referenced by /images/... path --
// Playwright's page.setContent() has no real page origin to resolve a
// relative URL against, so a plain <img src="/images/..."> would silently
// fail to load in the PDF. Read once per call rather than cached at module
// load so a logo file swap doesn't need a server restart to take effect.
function logoDataUri() {
  const buffer = fs.readFileSync(path.join(__dirname, '..', 'public', 'images', 'receiptap-logo.png'));
  return `data:image/png;base64,${buffer.toString('base64')}`;
}

/** `commission` must already be PAID (paidAt set) -- callers are
 * responsible for that check, same as the route's ownership check. */
async function generateAffiliateInvoicePDF(commission, affiliate, merchantName) {
  const html = await ejs.renderFile(
    path.join(VIEWS_DIR, 'affiliate-invoice-pdf.ejs'),
    {
      logoDataUri: logoDataUri(),
      invoiceNumber: `INV-${commission.id.slice(-8).toUpperCase()}`,
      affiliateName: affiliate.name,
      affiliateEmail: affiliate.email,
      paidDate: (commission.paidAt || commission.createdAt).toLocaleDateString('en-US', { dateStyle: 'medium' }),
      merchantName,
      rate: commission.rate,
      amount: (commission.amountCents / 100).toFixed(2),
      transferId: commission.stripeTransferId,
    },
    { views: [VIEWS_DIR] }
  );

  const browser = await chromium.launch();
  try {
    const page = await browser.newPage();
    await page.setContent(html, { waitUntil: 'networkidle' });
    return await page.pdf({
      format: 'Letter',
      printBackground: true,
      margin: { top: '0', bottom: '0', left: '0', right: '0' },
    });
  } finally {
    await browser.close();
  }
}

module.exports = { generateAffiliateInvoicePDF };
